import pyomo.environ as pyo

# All numeric constants from the problem
DATA = {
    "old_capacity": 100,      # bottles an old van carries
    "new_capacity": 80,       # bottles a new van carries
    "old_pollution": 50,      # pollution units per old van
    "new_pollution": 30,      # pollution units per new van
    "min_bottles": 5000,      # bottles that must be shipped
    "max_new_vans": 30,       # at most this many new vans may be used
}

# Van types
VANS = ["old", "new"]


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.VANS = pyo.Set(initialize=VANS)

    # Decision variables: number of each van type (indivisible vehicles)
    def van_bounds(m, v):
        if v == "new":
            return (0, d["max_new_vans"])
        return (0, None)

    model.x = pyo.Var(
        model.VANS,
        within=pyo.NonNegativeIntegers,
        bounds=van_bounds,
    )

    # Constraint: ship at least the required number of bottles
    def capacity_rule(m):
        return (
            d["old_capacity"] * m.x["old"]
            + d["new_capacity"] * m.x["new"]
            >= d["min_bottles"]
        )

    model.bottle_demand = pyo.Constraint(rule=capacity_rule)

    # Constraint: at most max_new_vans new vans (explicit, per problem text)
    def max_new_rule(m):
        return m.x["new"] <= d["max_new_vans"]

    model.max_new_vans = pyo.Constraint(rule=max_new_rule)

    # Objective: minimise total pollution
    def pollution_rule(m):
        return (
            d["old_pollution"] * m.x["old"]
            + d["new_pollution"] * m.x["new"]
        )

    model.obj = pyo.Objective(expr=pollution_rule, sense=pyo.minimize)

    return model


